func validate(identifier) -> bool {
    /* Validates a student id from the Pontifical Catholic University of Chile

    Args:
        identifier: student identifier (string or number)
    Returns:
        True if it is valid, False otherwise
    */

    if not identifier {
        return false;
    }

    let identifier_str = str(identifier);
    let student_number = identifier_str[:-1];
    let given_digit = identifier_str[-1].upper();

    let counter = 2;
    let total = 0;

    for char in reversed(student_number) {
        if not char.isdigit() {
            return false;
        }

        total += int(char) * counter;
        counter += 1;
        if counter > 8 {
            counter = 2;
        }
    }

    let digit = str(11 - total % 11);
    if digit == "10" {
        digit = "J";
    } else if digit == "11" {
        digit = "0";
    }

    return given_digit == digit;
}
