"""Determine whether a particular item should be exported as part of this export run."""
def skipExport(
    item: dict[str, dict[str, str | bool | int | float | None]],
    all: bool,
    metadataProperty: str
) -> bool | str | int | float | None {
    # If all flag is true, export everything
    if all:
        return false

    # Check if item has metadata property
    if metadataProperty in item:
        # If metadata property exists and is false, skip export
        if item[metadataProperty] is false:
            return true
        # If metadata property exists and is true, don't skip
        if item[metadataProperty] is true:
            return false

    # Default behavior - don't skip if no metadata property found
    return false
}

