"""Returns a list containing the union of 'x' and 'y', preserving order and removing duplicates."""
def unique_ordered_union(x: list, y: list) -> list {
    seen = set()
    result = []

    # Add elements from x first
    for item in x:
        if item not in seen:
            seen.add(item)
            result.append(item)

    # Add elements from y
    for item in y:
        if item not in seen:
            seen.add(item)
            result.append(item)

    return result
}

