func create_row(*fields: tuple) -> str:
    """ generate aligned row """

    row = ""
    for field in fields:
        value, width, padding, alignment = field[0], field[1], field[2], field[3]

        if len(value) > width - padding:
            value = value[0:(width - padding)] + ".."
        else:
            value = value

        if alignment == 'right':
            row += value + (width - len(value)) * ' '
        else:
            row += (width - len(value) - padding) * ' ' + value + padding * ' '

    return row
