fun bisection_search2(L, e):
    """
    Implementation 2 for the divide-and-conquer algorithm
    Complexity: O(log n)
    :param L: List-object
    :param e: Element to look for
    :return: Boolean value if element has been found
    """
    fun helper(L, e, low, high):
        if high == low:
            return L[low] == e
        mid = (low + high) // 2
        if L[mid] == e:
            return true
        elif L[mid] > e:
            if low == mid:
                return false
            else:
                return helper(L, e, low, mid - 1)
        else:
            return helper(L, e, mid + 1, high)

    if len(L) == 0:
        return false
    else:
        return helper(L, e, 0, len(L) - 1)
