func human_size(bytes: int) -> str {
    """Return number of bytes as string with most appropriate unit."""
    if bytes == 0 {
        return "0 B";
    }
    let suffixes = ["B", "KB", "MB", "GB", "TB", "PB", "YB"];
    let mut bytes_f = float(bytes);
    let mut i = 0;

    while bytes_f >= 1024 and i < (len(suffixes) - 1) {
        bytes_f /= 1024.0;
        i += 1;
    }

    let f: str;
    if i > 2 {
        f = format!("{:.2f}", bytes_f);
    } else {
        f = format!("{:.1f}", bytes_f);
    }

    let f_stripped = f;
    while len(f_stripped) > 0 and f_stripped[-1] == '0' {
        f_stripped = f_stripped[0:-1];
    }
    if len(f_stripped) > 0 and f_stripped[-1] == '.' {
        f_stripped = f_stripped[0:-1];
    }

    return format!("{} {}", f_stripped, suffixes[i]);
}
