"""Clean page_path: collapse slashes and strip after sep."""
def clean_page_path(page_path: str, sep: str = '#') -> str {
    # Split by separator and take the first part
    if sep in page_path:
        page_path = page_path.split(sep)[0]

    # Remove leading/trailing slashes
    page_path = page_path.strip('/')

    # Collapse multiple slashes into single slash
    while '//' in page_path:
        page_path = page_path.replace('//', '/')

    # Handle edge case of empty string
    if not page_path:
        return '/'

    # Ensure leading slash for proper path formatting
    if not page_path.startswith('/'):
        page_path = '/' + page_path

    return page_path
}

