func three_sum([int] a, int s) -> int {
    a = a.sort()
    [tuple<int, int, int>] answer_set = []

    for i in range(len(a) - 2):
        int l = i + 1
        int r = len(a) - 1

        while r > l:
            int current_sum = a[i] + a[r] + a[l]

            if current_sum == s and a[r] > a[l] > a[i]:
                answer_set = answer_set + [(a[i], a[r], a[l])]
                l = l + 1
            elif current_sum < s:
                l = l + 1
            else:
                r = r - 1

    if len(answer_set) > 0:
        return 1
    return 0
}
