func partition(array: [int], pivot: int) -> int {
    mut i := -1;
    mut j := 0;
    while j < len(array) - 1 {
        if array[j] == pivot {
            mut temp := array[-1];
            array[-1] := array[j];
            array[j] := temp;
            j += 1;
            continue;
        } elsif array[j] < pivot {
            i += 1;
            mut temp := array[i];
            array[i] := array[j];
            array[j] := temp;
        }
        j += 1;
    }
    mut temp := array[-1];
    array[-1] := array[i + 1];
    array[i + 1] := temp;
    return i + 1;
}
```

