func median_s(sorted_seq: [float]) -> float {
    """Return the median value of `sorted_seq`.

    >>> median ([1, 2, 2, 3, 14])
    2

    >>> median ([1, 2, 2, 3, 3, 14])
    2.5

    """
    let l = len(sorted_seq);
    let result: float;
    if l % 2 {
        result = sorted_seq[l // 2];
    } else {
        let l_new = l - 1;
        result = (sorted_seq[l_new // 2] + sorted_seq[l_new // 2 + 1]) / 2.0;
    }
    return result;
}
