walker power_set {
    has list[set] subsets = [];

    public func size_subsets(int size, list any current, set any values) {
        /* Finds all subsets of a given size in a set. */
        // Base Case: the current subset is full
        if len(current) == size {
            // add the current subset to the output (if not already there)
            set any current_set = set(current);
            bool found = false;
            for subset in self.subsets {
                if subset == current_set {
                    found = true;
                    break;
                }
            }
            if not found {
                self.subsets += [current_set];
            }
        } else { // len(current) < size
            // iterate over adding the others
            for item in values {
                any new_item = item;
                // add one more value to the current subset
                current += [new_item];
                set any new_values = set();
                for v in values {
                    if v != new_item {
                        new_values += [v];
                    }
                }
                self.size_subsets(size, current, new_values);
                // remove one of the elements, so we reach all possibilities
                current = current[:-1];
            }
        }
        return null;
    }

    public func power_set(set any values) -> int {
        // A: init the set for the return value
        self.subsets = [];

        // B: iterate over all possible sizes
        for size in range(1, len(values) + 1) {
            // add the subsets of the given size to the output
            self.size_subsets(size, [], values);
        }

        // C: return all the subsets
        return len(self.subsets);
    }
}
