"""The length of the string after evaluating."""
def parsed_length(line: str) -> int {
    # Remove leading and trailing whitespace
    line = line.strip()

    # If the line is empty, return 0
    if not line:
        return 0

    # If the line starts with a quote, it's a string literal
    if line.startswith('"') or line.startswith("'"):
        # Find the matching quote
        quote_char = line[0]
        end_quote = line.find(quote_char, 1)

        # If we found a matching quote, return the length of the string content
        if end_quote != -1:
            # Extract the string content (without quotes)
            content = line[1:end_quote]
            # Return the length of the content
            return len(content)
        else:
            # If no matching quote, return the length of the entire line
            return len(line)

    # For non-string lines, return the length of the line
    return len(line)
