"""Define region of image to crop."""
def get_crop_range(maxX: int, maxY: int, size: int = 32) -> tuple[int, int, int, int] {
    # Calculate crop boundaries
    cropX = maxX - size
    cropY = maxY - size
    cropWidth = size
    cropHeight = size

    # Ensure crop region stays within image bounds
    if cropX < 0:
        cropX = 0
        cropWidth = size + cropX
    if cropY < 0:
        cropY = 0
        cropHeight = size + cropY

    # Ensure crop dimensions don't exceed image bounds
    if cropX + cropWidth > maxX:
        cropWidth = maxX - cropX
    if cropY + cropHeight > maxY:
        cropHeight = maxY - cropY

    return (cropX, cropY, cropWidth, cropHeight)
}

