func human_size(num: float, suffix: str := 'B') -> str:
    """
    Convert bytes length to a human-readable version
    """
    let units = ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi']
    let num_ref = num
    for unit in units:
        if abs(num_ref) < 1024.0:
            return "{0:3.1f}{1!s}{2!s}".format(num_ref, unit, suffix)
        num_ref /= 1024.0
    return "{0:.1f}{1!s}{2!s}".format(num_ref, 'Yi', suffix)
