"""Remove a single extension from a file name, if present."""
def strip_extension(name: str) -> str {
    last_dot = name.rfind(".");
    if last_dot == -1:
        return name
    # Check if the dot is not at the beginning or end
    if last_dot == 0 or last_dot == len(name) - 1:
        return name
    # Check if there's a valid extension (at least one character after the dot)
    if last_dot < len(name) - 1:
        return name[:last_dot]
    return name
}

